class BillingMeter(_rt.WireEnum):
    """What is being charged for. Each meter counts in one base unit, and its allowance and its rate are expressed in that same unit.

    Serialized as the member name. A value this SDK version does not know is kept as a pseudo-member.
    """

    STANDARD = "Standard"
    """Apps, interactions and ingestion, counted in seconds of runner-held time."""

    PREMIUM = "Premium"
    """Capsules and code pipelines, counted in GiB-seconds: the runner class's allocated GiB × seconds held."""

    STORAGE = "Storage"
    """Stored data above the tier's storage cap, counted in GB-hours (1 GB = 10^9 bytes)."""

    WEB_SEARCH = "WebSearch"
    """Web searches, counted in pages of results."""

    WEB_FETCH = "WebFetch"
    """Web fetches, counted in fetch units (see `WebFetchUnitTable`)."""


class BillingNoticeKind(_rt.WireEnum):
    """What a billing notice is about.

    Serialized as the member name. A value this SDK version does not know is kept as a pseudo-member.
    """

    OUT_OF_CREDIT = "OutOfCredit"
    """The tenant is out of credit: nothing new starts, and what was running is stopped, until it tops up or upgrades."""

    CREDIT_RESTORED = "CreditRestored"
    """The tenant has credit again after being out of it: work can start again."""

    ALLOWANCE_USED = "AllowanceUsed"
    """On a plan without top-ups, one allowance is used up for the billing period (see `meter`)."""

    LOW_BALANCE = "LowBalance"
    """The balance fell below the tenant's low-balance alert."""

    PAYMENT_FAILED = "PaymentFailed"
    """A renewal payment failed: the tenant is on Free now, and its data is kept as it is until `frozenUntilUtc`. Paying the renewal before then puts it back on `previousTier`."""

    FREEZE_REMINDER = "FreezeReminder"
    """A reminder, 7, 21 and 28 days after a failed renewal payment, that it is still unpaid (see `frozenUntilUtc`)."""

    FREEZE_ENDED = "FreezeEnded"
    """The time to pay a failed renewal ran out: the subscription is cancelled, and Free's limits apply in full."""

    PLAN_RESTORED = "PlanRestored"
    """A failed renewal was paid: the tenant is back on `tier`."""

    PLAN_CHANGED = "PlanChanged"
    """The plan changed: a subscription started, an upgrade, or a change booked for the renewal took effect (see `tier`)."""

    MOVED_TO_FREE = "MovedToFree"
    """The subscription ended (cancelled, or its payments gave up): the tenant is on Free."""

    AUTO_TOP_UP_FAILED = "AutoTopUpFailed"
    """An automatic top-up couldn't be charged, so automatic top-ups are off until the card or the settings are saved again."""


