class BuildRecord(_rt.WireModel):
    """One attempt to validate or deploy a project into a namespace, recorded whatever its outcome: who, when, how long, what was sent (a list of files with hashes, and the files themselves up to a limit), the build log, and what a deploy produced. Its `id` is the `buildId` the build returned. Records are kept for 90 days.

    Every list and text is capped in size; the `…Truncated` flags say when a cap applied. The counts and totals are always exact.
    """

    namespace_name: str = _p.Field(alias="namespaceName")
    """The namespace named in the route (at most 256 characters)."""

    namespace_id: _t.Optional[str] = _p.Field(default=None, alias="namespaceId")
    """The namespace's id when it existed once the build finished (a first deploy creates it); else null.

    Format: uuid.
    """

    user_display_name: _t.Optional[str] = _p.Field(default=None, alias="userDisplayName")
    """The caller's name when the build ran (a snapshot: a later rename does not change it)."""

    user_email_address: _t.Optional[str] = _p.Field(default=None, alias="userEmailAddress")
    """The caller's e-mail address when the build ran (a snapshot)."""

    authentication_method: BuildAuthenticationMethod = _p.Field(alias="authenticationMethod")
    """How the caller authenticated."""

    api_key_id: _t.Optional[str] = _p.Field(default=None, alias="apiKeyId")
    """The id of the API key the build was sent with (never the key itself); null for a bearer token.

    Format: uuid.
    """

    is_deploy: bool = _p.Field(alias="isDeploy")
    """Whether the request asked to deploy rather than only validate."""

    is_deployed: bool = _p.Field(alias="isDeployed")
    """Whether the definitions were deployed (a successful build with `isDeploy`)."""

    outcome: BuildOutcome
    """How the build ended."""

    is_faulted: bool = _p.Field(alias="isFaulted")
    """Whether the build stopped on an unexpected error (a 5xx) rather than failing with a log; `outcome` is then `Failed`."""

    duration_milliseconds: int = _p.Field(alias="durationMilliseconds")
    """How long the build took on the server, in milliseconds."""

    counts: BuildRecordCounts
    """How many files of each kind the request carried."""

    error_count: int = _p.Field(alias="errorCount")
    """Error entries in the full build log (exact, even when `diagnostics` is truncated)."""

    warning_count: int = _p.Field(alias="warningCount")
    """Warning entries in the full build log (exact)."""

    item_count: int = _p.Field(alias="itemCount")
    """Source files the request carried (exact, even when `items` is truncated)."""

    sources_bytes: int = _p.Field(alias="sourcesBytes")
    """Total UTF-8 size of every source file the request carried (exact)."""

    items: list[BuildRecordItem]
    """Every source file in request order, with its size and hash, up to 2,000."""

    items_truncated: bool = _p.Field(alias="itemsTruncated")
    """Whether `items` was cut short at its limit."""

    sources: list[BuildRecordSource]
    """The source files' text, whole files only, up to 2 MiB in total (text plus names). Files that do not fit are left out (their item reads `sourceStored: false`) and `sourcesTruncated` is set."""

    sources_truncated: bool = _p.Field(alias="sourcesTruncated")
    """Whether some source files were left out of `sources` to keep within its limit."""

    diagnostics: list[BuildRecordDiagnostic]
    """The build log as the response carried it, in order. Capped at 1,000 entries and 1 MiB of text; when the cap applies, errors are kept before warnings, then information, then debug entries."""

    diagnostics_truncated: bool = _p.Field(alias="diagnosticsTruncated")
    """Whether `diagnostics` was cut short at its limit."""

    deployed: list[BuildRecordDeployedResource]
    """What a deploy created, updated or left unchanged (empty for a validation), up to 2,000."""

    deployed_truncated: bool = _p.Field(alias="deployedTruncated")
    """Whether `deployed` was cut short at its limit."""

    validation_failures: list[BuildRecordValidationFailure] = _p.Field(alias="validationFailures")
    """Why a `Rejected` build was refused (the 400's failures, up to 20); empty otherwise."""

    user_created_by_id: str = _p.Field(alias="userCreatedById")
    """The id of the user who created it. A call made with an API key is recorded as the key's user.

    Format: uuid.
    """

    tenant_id: str = _p.Field(alias="tenantId")
    """The id of the tenant it belongs to.

    Format: uuid.
    """

    id: str
    """The unique id. Use it in `by-id` routes and wherever another object refers to this one.

    Format: uuid.
    """

    date_created: _rt.DotNetDateTime = _p.Field(alias="dateCreated")
    """When it was created, in UTC.

    Format: ISO-8601 date-time, up to 7 fractional digits.
    """

    date_updated: _rt.DotNetDateTime = _p.Field(alias="dateUpdated")
    """When it was last changed, in UTC.

    Format: ISO-8601 date-time, up to 7 fractional digits.
    """


