    """The step's name, unique within its phase."""

    agent_name: str = _p.Field(alias="agentName")
    """The agent that runs the step. When set, `targetRole` and `targetTags` are ignored; when empty, the step runs on an agent matching them."""

    target_role: _t.Optional[CodePipelineAgentRole] = _p.Field(default=None, alias="targetRole")
    """Instead of naming an agent, run on any agent with this role. Chosen when the run starts; parallel steps that name the same role are spread across different agents where there are enough."""

    target_tags: _t.Optional[list[str]] = _p.Field(default=None, alias="targetTags")
    """Instead of naming an agent, run on any agent carrying at least one of these tags (ignoring case). With `targetRole` as well, the agent must match both."""

    prompt: str
    """The step's prompt. It can use the same template syntax as interactions: `%%input:name%%` for a run input, `%%name%%` for a variable, `{{if}}` and `{{unless}}` blocks, and `@prompt(name)`, replaced with a prompt file when you deploy."""

    depends_on: _t.Optional[list[str]] = _p.Field(default=None, alias="dependsOn")
    """Other steps in the same phase that must finish before this one starts. One agent's steps always run in their listed order without it."""

    is_commitable: bool = _p.Field(alias="isCommitable")
    """Whether the agent's code changes are committed when the step finishes."""

    commit_repo_name: _t.Optional[str] = _p.Field(default=None, alias="commitRepoName")
    """For a run with several repositories, the `name` of the one this step commits to. Null: the first repository."""

    is_structured_output: bool = _p.Field(alias="isStructuredOutput")
    """Whether to ask the agent, after the step, for a structured summary of how it went (recorded as the step's `outputStructured`)."""

    output_json_schema: _t.Optional[str] = _p.Field(default=None, alias="outputJsonSchema")
    """A JSON schema the step's final result must match. Output that doesn't match is repaired where possible."""

    is_output_schema_required: bool = _p.Field(alias="isOutputSchemaRequired")
    """Whether the step fails when its result can't be made to match `outputJsonSchema`."""

    output_variable_name: _t.Optional[str] = _p.Field(default=None, alias="outputVariableName")
    """A variable to store the step's final result in, so later step prompts (`%%name%%`) and hooks can use it."""

    output_file_name: _t.Optional[str] = _p.Field(default=None, alias="outputFileName")
    """A file name to write the step's output to, in the run's `output_files/` folder."""

    pre_hook: _t.Optional[str] = _p.Field(default=None, alias="preHook")
    """The name of a hook (a Cogniscript method in the pipeline's hooks) to run before the step."""

    post_hook: _t.Optional[str] = _p.Field(default=None, alias="postHook")
    """The name of a hook to run after the step finishes."""

    on_fail_hook: _t.Optional[str] = _p.Field(default=None, alias="onFailHook")
    """The name of a hook to run when the step fails. It returns JSON with a `decision`: `"continue"` marks the step skipped and carries on, `"retry"` runs the step again, and `"fail"` fails it as usual."""

    is_new_session: bool = _p.Field(alias="isNewSession")
    """Whether the agent starts a fresh session for this step instead of continuing from its previous step. Use it for independent pieces of work, where earlier context would only confuse. Default `false`."""

    run_challenge_loop: bool = _p.Field(alias="runChallengeLoop")
    """Whether, after the step succeeds, the same agent is asked whether its work is really built and tested, and is sent its open concerns back until it says it is done or `maxCheckLoops` rounds have run. Each round is recorded in the step's `challengeLoopTurns`."""

    duration_warning: _t.Optional[_rt.DotNetTimeSpan] = _p.Field(default=None, alias="durationWarning")
    """Not used by code pipeline runs.

    Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
    """

    duration_auto_termination: _t.Optional[_rt.DotNetTimeSpan] = _p.Field(default=None, alias="durationAutoTermination")
    """The longest the step may run before it is stopped. Null: the phase's value, then the pipeline's, applies.

    Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
    """

    duration_activity_timeout: _t.Optional[_rt.DotNetTimeSpan] = _p.Field(default=None, alias="durationActivityTimeout")
    """How long the step may go without activity before it is stopped. Null: the phase's value, then the pipeline's, applies.

    Format: .NET TimeSpan "[-][d.]hh:mm:ss[.fffffff]".
    """


