class LoomThread(_rt.WireModel):
    """A thread: one memory. Weak alone, powerful when woven.

    Its standing in the loom is its `salience`, `weight × (1 − fray)`. Time alone never changes it: a thread frays only when it is put in front of an agent and goes unused, and tightens again when it is used. A thread accessed yesterday and one accessed five years ago stand equal if both still matter. The one exception is a thread that says when it stops holding (`until`): after that it is no longer woken into or offered.

    Threads are never deleted by forgetting. A cut releases the words and leaves a knot (`knot`); a reframe leaves a seam (`seams`). Only a tenant admin's erasure removes a thread, and that exists for data-subject erasure, not for memory.
    """

    loom_id: str = _p.Field(alias="loomId")
    """The loom that holds the thread.

    Format: uuid.
    """

    content: str
    """The thread's words. Empty once cut; the knot keeps the essence."""

    kind: ThreadKind
    """What kind of memory it is."""

    strand: ThreadStrand
    """Warp (foundational, never frays) or weft (contextual, can fray)."""

    weight: float
    """0..1: emotional significance, importance, meaning."""

    fray: float
    """0..1: how loose the thread has worked through disuse. Warp never frays."""

    decay_rate: DecayRate = _p.Field(alias="decayRate")
    """How quickly it frays when it is offered and goes unused."""

    subjects: list[str]
    """Who or what the thread is about, as named in conversation ("Ada", "the billing service")."""

    subject_keys: list[str] = _p.Field(alias="subjectKeys")
    """The `subjects`, normalised (lowercase, single-spaced) for matching."""

    tags: list[str]
    """Free-form tags."""

    cues: list[str]
    """Words the thread waits for (normalised: lowercase, single-spaced). When someone says one, the thread comes back to the agent that holds it: "remind me when the cello comes up"."""

    visibility: ThreadVisibility
    """Whether every agent bound to the loom may see it, or only the agent that wove it."""

    until: _t.Optional[_rt.DotNetDateTime] = None
    """When this stops holding, if it says: the day a reminder no longer matters ("the entry closes on Friday 30 October 2026"), or a plan has passed. After it, the thread is no longer woken into or offered; recall still finds it, marked as past. Null: it holds until it is let go.

    Format: ISO-8601 date-time, up to 7 fractional digits.
    """

    basis: ThreadBasis
    """What it rests on: said, the agent's own impression, or read somewhere (see `ThreadBasis`)."""

    pinned: bool
    """Held close: always part of what the agent wakes up knowing."""

    origin: ThreadOrigin
    """Who wove the thread, and from where."""

    companions: list[ThreadCompanion]
    """Threads this one has been used together with (see `ThreadCompanion`)."""

    provenance: _t.Optional[ThreadProvenance] = None
    """Set when the thread came from another loom (a gift, or inheritance when the loom was seeded). Null for a thread woven here, which is almost all of them."""

    can_travel: bool = _p.Field(alias="canTravel")
    """Whether this thread may be copied to another loom. Only shared knowledge travels: never a knot, a private note, a reflection (another agent's inner voice), an episode (a moment the recipient did not live, which would be a fabricated memory rather than knowledge), or an intention (a promise made to someone else).

    Computed by the server; ignored on input.
    """

    access_count: int = _p.Field(alias="accessCount")
    """Times recalled or used."""

    last_accessed_at: _t.Optional[_rt.DotNetDateTime] = _p.Field(default=None, alias="lastAccessedAt")
    """When the thread was last recalled or used (UTC). Null if it never has been.

    Format: ISO-8601 date-time, up to 7 fractional digits.
    """

    surfaced_count: int = _p.Field(alias="surfacedCount")
    """Times put in front of an agent (tapestry, suggestion, recall result)."""

    last_surfaced_at: _t.Optional[_rt.DotNetDateTime] = _p.Field(default=None, alias="lastSurfacedAt")
    """When the thread was last put in front of an agent (UTC). Null if it never has been.

    Format: ISO-8601 date-time, up to 7 fractional digits.
    """

    reinforcements: int
    """Times the same thread was woven again and reinforced instead of duplicated."""

    knot: _t.Optional[ThreadKnot] = None
    """What remains of a cut thread: when and why it was let go, and its essence. Null on a living thread."""

    seams: list[ThreadSeam]
    """The seams its reframes left, oldest first: what it said before each change, and why it changed."""

    revision: int
    """Goes up by one every time the thread is reframed, cut or pinned."""

    is_knot: bool = _p.Field(alias="isKnot")
    """True when the thread has been cut and only its knot remains.

    Computed by the server; ignored on input.
    """

    is_warp: bool = _p.Field(alias="isWarp")
    """True when the thread is warp: foundational, and never frays.

    Computed by the server; ignored on input.
    """

    is_intention: bool = _p.Field(alias="isIntention")
    """True when the thread is an intention: something to do when its moment comes.

    Computed by the server; ignored on input.
    """

    is_loose: bool = _p.Field(alias="isLoose")
    """Held loosely: an impression, or something read rather than said. Lighter, and never built on.

    Computed by the server; ignored on input.
    """

    salience: float
    """Standing in the loom: weight, loosened by fraying. Warp never frays.

    Computed by the server; ignored on input.
    """

    short_id: str = _p.Field(alias="shortId")
    """The 8-character id agents see and can refer back to.

    Computed by the server; ignored on input.
    """

    tenant_id: str = _p.Field(alias="tenantId")
    """The id of the tenant it belongs to.

    Format: uuid.
    """

    id: str
    """The unique id. Use it in `by-id` routes and wherever another object refers to this one.

    Format: uuid.
    """

    date_created: _rt.DotNetDateTime = _p.Field(alias="dateCreated")
    """When it was created, in UTC.

    Format: ISO-8601 date-time, up to 7 fractional digits.
    """

    date_updated: _rt.DotNetDateTime = _p.Field(alias="dateUpdated")
    """When it was last changed, in UTC.

    Format: ISO-8601 date-time, up to 7 fractional digits.
    """


